import { useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ReportSheet } from './ReportSheet.js';
import type { ReportTarget } from './report.js';
import styles from './Report.module.css';

/**
 * The quiet Report action that sits beside AI-written content: a flag and
 * the word, in the dim text colour, never louder than the content. `icon`
 * is the flag alone, for rows of icon tools (a Lex answer); it keeps its
 * name for screen readers and as a tooltip. The target is read when tapped,
 * so it is the text on screen at that moment.
 */
export function ReportButton({
  target,
  variant = 'text',
  label,
  className,
}: {
  target: ReportTarget | (() => ReportTarget);
  variant?: 'text' | 'icon';
  /** The accessible name; the visible word stays "Report". */
  label?: string | undefined;
  className?: string | undefined;
}): React.JSX.Element {
  const [open, setOpen] = useState<ReportTarget | undefined>(undefined);
  const name = label ?? t('report.actionLabel');
  return (
    <>
      <button
        type="button"
        className={cx(variant === 'icon' ? styles.iconButton : styles.textButton, className)}
        aria-label={name}
        title={variant === 'icon' ? name : undefined}
        aria-haspopup="dialog"
        onClick={() => {
          setOpen(typeof target === 'function' ? target() : target);
        }}
      >
        <Icon name="flag" size={variant === 'icon' ? 16 : 14} weight={1.9} />
        {variant === 'text' && <span>{t('report.action')}</span>}
      </button>
      {open !== undefined && (
        <ReportSheet
          target={open}
          onClose={() => {
            setOpen(undefined);
          }}
        />
      )}
    </>
  );
}
